                >
                  {artwork.price}
                </span>
                {!isSold && !isComingSoon && (
                  <span className="font-label text-[9px] text-neutral-600 uppercase tracking-widest border border-outline-variant/20 px-2 py-1">
                    Fixed Price
                  </span>
